// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address a1, address a2, uint256 amt1, uint256 amt2) public {
        vm.assume(a1 != address(0) && a2 != address(0) && a1 != a2 && a1 != address(c) && a2 != address(c));
        amt1 = bound(amt1, 1, 100 ether);
        amt2 = bound(amt2, 1, 100 ether);

        // actor a1 deposits via fallback
        vm.deal(a1, amt1);
        vm.prank(a1);
        (bool dp1, ) = address(c).call{value: amt1}("");
        assertTrue(dp1);

        // first withdraw succeeds for everyone
        vm.prank(a1);
        bool ok1;
        try c.withdraw() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);

        // actor a2 deposits
        vm.deal(a2, amt2);
        vm.prank(a2);
        (bool dp2, ) = address(c).call{value: amt2}("");
        assertTrue(dp2);

        // RULE: a later withdraw by any other actor with a positive balance must succeed
        vm.prank(a2);
        bool ok2;
        try c.withdraw() { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2 && c.balances(a2) == 0);
    }
}
